<script setup lang="ts">import {ref} from 'vue';import {api} from '../../api';import {t} from '../../locales';import '../../styles/app.scss';const step=ref(1);const account=ref('');const code=ref('');const password=ref('');async function next(){if(step.value===1&&!account.value)return uni.showToast({title:t('输入邮箱或手机号'),icon:'none'});if(step.value===2&&!code.value)return uni.showToast({title:t('输入验证码'),icon:'none'});try{if(step.value===1)await api.sendLoginCode(account.value,2);if(step.value===2){step.value++;return}if(step.value===3){await api.forgetPassword({email:account.value,password:password.value,code:code.value});uni.showToast({title:t('密码已重置'),icon:'none'});setTimeout(()=>uni.navigateBack(),500);return}step.value++}catch(error:any){uni.showToast({title:error?.message||t('操作失败'),icon:'none'})}}</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{t('找回密码')}}</text></view><view class="inner-main"><view class="inner-heading">{{t('找回密码')}}</view><view class="inner-subtitle">{{t('按步骤验证身份并设置新密码')}}</view><view class="inner-tabs"><text v-for="n in 3" :key="n" class="inner-tab" :class="{active:step===n}">{{t('步骤')}} {{n}}</text></view><view class="inner-card"><view v-if="step===1"><view class="form-field"><text class="form-label">{{t('邮箱或手机号')}}</text><input v-model="account" class="form-input" :placeholder="t('输入账号')"/></view><button class="action-button" @click="next">{{t('获取验证码')}}</button></view><view v-else-if="step===2"><view class="form-field"><text class="form-label">{{t('验证码')}}</text><input v-model="code" class="form-input" :placeholder="t('输入验证码')"/></view><button class="action-button" @click="next">{{t('验证')}}</button></view><view v-else><view class="form-field"><text class="form-label">{{t('新密码')}}</text><input v-model="password" class="form-input" password :placeholder="t('设置新密码')"/></view><button class="action-button" @click="next">{{t('完成')}}</button></view></view></view></view></template>
